            data.setdefault(section,{})[m.group(1).lower()]=val
    except OSError: pass
    return data
def parse(line):
    s=line.rstrip('\n'); d={'raw':s,'done':False,'pri':'','created':'','finished':'','tags':{}}
    if s.startswith('x '):
